package org.ofdrw.layout.element.canvas;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertNull;

import org.junit.jupiter.api.Test;

class NamedColorRgbTests {

    @Test
    void convertsSupportedColorRepresentationsToRgbValues() {
        assertArrayEquals(new int[]{255, 0, 0}, NamedColor.rgb("RED"));
        assertArrayEquals(new int[]{0, 255, 0}, NamedColor.rgb("#00FF00"));
        assertArrayEquals(new int[]{12, 34, 56}, NamedColor.rgb("rgb(12, 34, 56)"));
        assertArrayEquals(new int[]{12, 34, 56}, NamedColor.rgb("rgba(12, 34, 56, 0.5)"));
    }

    @Test
    void returnsNullForMissingOrInvalidInputWithoutThrowing() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb(""));
        assertNull(NamedColor.rgb("not-a-color"));

        int[] result = assertDoesNotThrow(() -> NamedColor.rgb("rgb(10, 20)"));
        assertNull(result);
    }
}

