package org.ofdrw.layout.element.canvas;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertNull;

import org.junit.jupiter.api.Test;

class NamedColorRgbTests {

    @Test
    void convertsNamedColorCaseInsensitivelyAndTrimsWhitespace() {
        int[] result = NamedColor.rgb("  ReD  ");

        assertArrayEquals(new int[]{255, 0, 0}, result);
    }

    @Test
    void convertsHexadecimalColorToRgbComponents() {
        int[] result = NamedColor.rgb("#1A2B3C");

        assertArrayEquals(new int[]{26, 43, 60}, result);
    }

    @Test
    void convertsRgbTextToThreeColorComponents() {
        int[] result = NamedColor.rgb("rgb(12, 34, 56)");

        assertArrayEquals(new int[]{12, 34, 56}, result);
    }

    @Test
    void rgbaTextReturnsOnlyRgbComponents() {
        int[] result = NamedColor.rgb("rgba(12, 34, 56, 0.5)");

        assertArrayEquals(new int[]{12, 34, 56}, result);
    }

    @Test
    void invalidInputReturnsNullWithoutThrowing() {
        int[] result = assertDoesNotThrow(() -> NamedColor.rgb("rgb(12, 34)"));

        assertNull(result);
    }

    @Test
    void nullAndEmptyInputsReturnNull() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb(""));
    }
}

