import org.ofdrw.core.basicStructure.pageObj.Page;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.signatures.appearance.StampAnnot;
import org.ofdrw.reader.OFDReader;
import org.ofdrw.sign.SignIDProvider;

import java.io.InputStream;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class RidingStampPosGetAppearanceTests {

    @Test
    public void generatesOneAnnotationPerPageWithConfiguredRepeatedClipCount() throws Exception {
        OFDReader reader = new OFDReader((InputStream) null) {
            @Override
            public int getNumberOfPages() {
                return 3;
            }

            @Override
            public Page getPage(int pageNum) {
                return null;
            }

            @Override
            public ST_Box getPageSize(Page page) {
                return new ST_Box(0, 0, 100, 80);
            }
        };

        SignIDProvider idProvider = new SignIDProvider() {
            private int nextId;

            @Override
            public void setCurrentMaxSignId(String maxSignId) {
                nextId = Integer.parseInt(maxSignId.substring(1));
            }

            @Override
            public String incrementAndGet() {
                return String.format("s%03d", ++nextId);
            }

            @Override
            public String get() {
                return String.format("s%03d", nextId);
            }

            @Override
            public int parse(String id) {
                return Integer.parseInt(id.substring(1));
            }
        };

        RidingStampPos position =
                new RidingStampPos(Side.Right, null, 2, 20, 10, 0);

        List<StampAnnot> appearances = position.getAppearance(reader, idProvider);

        assertEquals(3, appearances.size());
        assertEquals("s001", appearances.get(0).getID());
        assertEquals("s002", appearances.get(1).getID());
        assertEquals("s003", appearances.get(2).getID());

        for (StampAnnot appearance : appearances) {
            assertEquals(20.0, appearance.getBoundary().getWidth(), 1e-9);
            assertEquals(10.0, appearance.getBoundary().getHeight(), 1e-9);
            assertEquals(10.0, appearance.getClip().getWidth(), 1e-9);
            assertEquals(10.0, appearance.getClip().getHeight(), 1e-9);
        }
    }
}

