import static org.junit.jupiter.api.Assertions.assertTrue;

class RidingStampPosGetAppearanceTests {

    @Test
    void topStampWithPartialClipCountUsesStampHeightForVerticalClips() throws Exception {
        TestReader reader = allocateReader();
        Page page = new Page();
        ST_RefID pageReference = new ST_RefID(1L);
        ST_ID pageObjectId = new ST_ID(2L) {
            @Override
            public ST_RefID ref() {
                return pageReference;
            }
        };

        reader.page = page;
        reader.pageObjectId = pageObjectId;

        SignIDProvider idProvider = new SignIDProvider() {
            private int next;

            @Override
            public void setCurrentMaxSignId(String maxSignId) {
                next = Integer.parseInt(maxSignId.substring(1));
            }

            @Override
            public String incrementAndGet() {
                return "s" + (++next);
            }

            @Override
            public String get() {
                return "s" + next;
            }

            @Override
            public int parse(String id) {
                return Integer.parseInt(id.substring(1));
            }
        };

        double stampWidth = 40;
        double stampHeight = 20;
        RidingStampPos position =
                new RidingStampPos(Side.Top, 7d, 2, stampWidth, stampHeight, 0);

        List<StampAnnot> appearance = position.getAppearance(reader, idProvider);

        assertEquals(3, appearance.size());

        Set<String> ids = new HashSet<>();
        for (StampAnnot annot : appearance) {
            assertNotNull(annot.getBoundary());
            assertEquals(stampWidth, annot.getBoundary().getWidth(), 1e-9);
            assertEquals(stampHeight, annot.getBoundary().getHeight(), 1e-9);
            assertEquals(pageReference, annot.getPageRef());
            assertTrue(ids.add(annot.getID()));
        }

        ST_Box finalClip = appearance.get(2).getClip();
        assertNotNull(finalClip);
        assertEquals(stampWidth, finalClip.getWidth(), 1e-9);
        assertEquals(stampHeight / 3, finalClip.getHeight(), 1e-9);
    }

    private static TestReader allocateReader() throws Exception {
        Field field = Unsafe.class.getDeclaredField("theUnsafe");
        field.setAccessible(true);
        Unsafe unsafe = (Unsafe) field.get(null);
        return (TestReader) unsafe.allocateInstance(TestReader.class);
    }

    private static final class TestReader extends OFDReader {
        private Page page;
        private ST_ID pageObjectId;

        private TestReader() throws Exception {
            super((String) null);
        }

        @Override
        public int getNumberOfPages() {
            return 3;
        }

        @Override
        public Page getPage(int pageIndex) {
            return page;
        }

        @Override
        public ST_Box getPageSize(Page page) {
            return new ST_Box(0, 0, 200, 100);
        }

        @Override
        public ST_ID getPageObjectId(int pageIndex) {
            return pageObjectId;
        }
    }
}

